insert into i18n_bundles (locale, code, value) values ('fa', 'fasting.reason-groups.voluntary.reasons[3].cites[4].quote', 'روزه سه روز از هر ماه، روزه تمام عمر است؛ و روزهای روشن، سیزدهم، چهاردهم و پانزدهم است.');
