insert into i18n_bundles (locale, code, value) values ('fa', 'fasting.reason-groups.voluntary.reasons[3].cites[5].quote', 'دوست صمیمی‌ام، پیامبر اکرم (ص)، مرا به سه چیز سفارش کرد: روزه سه روز از هر ماه، دو رکعت نماز ضحی و خواندن نماز وتر پیش از خواب.');
