insert into i18n_bundles (locale, code, value) values ('fa', 'fasting.reason-groups.voluntary.reasons[3].cites[6].quote', 'دوست صمیمی‌ام، پیامبر اکرم (ص)، مرا به سه چیز سفارش کرد که هرگز ترکشان نمی‌کنم؛ از آن جمله روزه سه روز از هر ماه است.');
