insert into i18n_bundles (locale, code, value) values ('fa', 'fasting.reason-groups.voluntary.reasons[3].cites[0].quote', 'ای ابوذر، اگر از ماهی سه روز روزه می‌داری، سیزدهم، چهاردهم و پانزدهم را روزه بدار.');
