insert into i18n_bundles (locale, code, value) values ('fa', 'fasting.reason-groups.voluntary.reasons[4].cites[1].intro', 'اسامه بن زید (رضی‌الله‌عنه) روایت کرده است که رسول خدا (ص) فرمودند:');
insert into i18n_bundles (locale, code, value) values ('fa', 'fasting.reason-groups.voluntary.reasons[4].cites[1].quote', 'آن دو روز، روزهایی هستند که اعمال در آن‌ها به پروردگار جهانیان عرضه می‌شود؛ و من دوست دارم عملم در حالی عرضه شود که روزه‌ام.');
