insert into i18n_bundles (locale, code, value) values ('fa', 'fasting.reason-groups.voluntary.reasons[4].cites[2].intro', 'ابوقتاده انصاری (رضی‌الله‌عنه) از پیامبر اکرم (ص) درباره روزه دوشنبه پرسید و ایشان فرمودند:');
